////Bit  8:0 -       0   - INTISR24 interrupt source select in int_map
//`define AOCPU_IRQ_SEL13           8'h1d
////Bit 24:16-       0   - INTISR27 interrupt source select in int_map
////Bit  8:0 -       0   - INTISR26 interrupt source select in int_map
//`define AOCPU_IRQ_SEL14           8'h1e
////Bit 24:16-       0   - INTISR29 interrupt source select in int_map
////Bit  8:0 -       0   - INTISR28 interrupt source select in int_map
//`define AOCPU_IRQ_SEL15           8'h1f
////Bit 24:16-       0   - INTISR31 interrupt source select in int_map
////Bit  8:0 -       0   - INTISR30 interrupt source select in int_map
#define AOCPU_STS00_BYCPU                          ((0x0020  << 2) + 0xfe09c000)
//Bit 31:0-       0   - reserved
#define AOCPU_STS01_BYCPU                          ((0x0021  << 2) + 0xfe09c000)
//Bit 31:0-       0   - reserved
#define AOCPU_STS02_BYCPU                          ((0x0022  << 2) + 0xfe09c000)
//Bit 31:0-       0   - reserved
#define AOCPU_STS03_BYCPU                          ((0x0023  << 2) + 0xfe09c000)
//Bit 31:0-       0   - reserved
#define AOCPU_STS04_BYCPU                          ((0x0024  << 2) + 0xfe09c000)
//Bit 31:0-       0   - reserved
#define AOCPU_STS05_BYCPU                          ((0x0025  << 2) + 0xfe09c000)
//Bit 31:0-       0   - reserved
#define AOCPU_STS06_BYCPU                          ((0x0026  << 2) + 0xfe09c000)
//Bit 31:0-       0   - reserved
#define AOCPU_STS07_BYCPU                          ((0x0027  << 2) + 0xfe09c000)
//Bit 31:0-       0   - reserved
#define AOCPU_TIMER_DIV                            ((0x0028  << 2) + 0xfe09c000)
