// RW [31: 0] aes_iv[127:96]
#define HDMI20_AES_IV3                             ((0x0007  << 2) + 0xfe482000)
// WO [    0] 1=Load aes_iv[127:0]
#define HDMI20_AES_IV_LOAD                         ((0x0008  << 2) + 0xfe482000)
#define HDMI20_AES_KEY_WORD0                       ((0x0009  << 2) + 0xfe482000)
